package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaIdDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("Tiga Quls (Mu'awwidhat)", "(Surah al-Ikhlas) Katakanlah: Dialah Allah yang Maha Esa. Allah, Yang Maha Cukup. Dia tidak memperanakkan dan tidak dilahirkan. Dan tidak ada seorangpun yang sebanding dengan-Nya.\n\n(QS. Al-Falaq) Katakanlah: Aku berlindung kepada Tuhan Yang Maha Esa, dari keburukan apa yang diciptakan-Nya, dari keburukan kegelapan ketika mengendap, dari keburukan orang-orang yang membuat simpul, dan dari keburukan orang-orang yang iri hati jika dia iri.\n\n(Surah an-Nas) Katakanlah: Aku berlindung kepada Tuhan umat manusia, Raja umat manusia, Tuhan umat manusia, dari kejahatan para pembisik yang mundur, yang berbisik ke dalam hati manusia, dari kalangan jin dan manusia.", "Tiga surah itu tiga kali setiap pagi dan sore, dan sebelum tidur, tiuplah ke tangan dan usapkan ke seluruh tubuh.", "Membacanya tiga kali pagi dan sore sudah cukup untuk melawan segalanya."),
        "dua_sabr" to DuaText("Untuk Kesabaran dan Ketabahan", "Ya Tuhan kami, curahkanlah kesabaran kepada kami, kuatkan kaki kami dan bantulah kami melawan orang-orang kafir.", "Di saat-saat sulit dan konfrontasi.", "Doa tentara Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Pengampunan dan Perlindungan dari Api", "Ya Tuhan kami, kami telah beriman, maka ampunilah dosa-dosa kami dan peliharalah kami dari siksa api neraka.", "Sebuah doa Al-Qur'an.", "Sebuah doa yang disebutkan di antara sifat-sifat orang yang bertakwa."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Petunjuk dalam Urusan Kita (Ashab al-Kahfi)", "Ya Tuhan kami, berilah kami rahmat dari-Mu dan sediakan bagi kami petunjuk yang benar dalam urusan kami.", "Doa Penduduk Gua.", "Bimbingan dalam pengambilan keputusan dan situasi sulit."),
        "dua_musa_faqir" to DuaText("Doa Musa (AS) untuk Rezeki", "Ya Tuhanku, aku benar-benar membutuhkan kebaikan apa pun yang Engkau kirimkan kepadaku.", "Mencari rezeki dan kebaikan — doa Musa (AS) di Madyan.", "Setelah doa ini, Allah menganugerahkan Musa (AS) sebuah rumah, pekerjaan dan seorang istri."),
        "dua_ayyub" to DuaText("Doa Ayyub (AS) dalam Penyakit", "(Tuhanku,) celaka telah menimpaku, dan Engkaulah Yang Maha Penyayang di antara Yang Maha Penyayang.", "Dalam penyakit dan penderitaan.", "Allah menghilangkan penderitaan Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Mati Sebagai Seorang Muslim (Yusuf AS)", "Pencipta langit dan bumi, Engkaulah Pelindungku di dunia dan di akhirat. Matikan aku sebagai seorang Muslim dan bergabunglah dengan orang-orang yang saleh.", "Doa untuk akhir yang baik.", "Doa Nabi Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Perlindungan dari Bisikan Setan", "Ya Tuhanku, aku berlindung kepada-Mu dari bisikan setan, dan aku berlindung kepada-Mu ya Tuhanku, agar mereka tidak mendekatiku.", "Berlindung dari bisikan setan.", "Doa Al-Qur'an untuk mencari perlindungan."),
        "dua_bad_character" to DuaText("Berlindung dari Karakter Buruk", "Ya Allah, aku berlindung kepada-Mu dari sifat buruk, perbuatan buruk, dan keinginan jahat.", "Berlindung dari akhlak, perbuatan dan hawa nafsu yang buruk.", "Doa perlindungan dari Nabi ﷺ."),
        "dua_zawal_nimah" to DuaText("Perlindungan dari Kehilangan Berkah", "Ya Allah, aku berlindung kepada-Mu dari hilangnya nikmat-Mu, dari perubahan kesejahteraan yang Engkau berikan, dari siksa-Mu yang tiba-tiba, dan dari segala kemurkaan-Mu.", "Berlindung dari kehilangan keberkahan dan dari musibah yang tiba-tiba.", "Doa Nabi ﷺ."),
        "dua_useless_knowledge" to DuaText("Berlindung dari Ilmu yang Tidak Bermanfaat", "Ya Allah, aku berlindung kepada-Mu dari ilmu yang tidak bermanfaat, dari hati yang tidak takut, dari jiwa yang tidak pernah puas, dan dari doa yang tidak terkabul.", "Berlindung dari ilmu yang sia-sia dan hati yang tidak takut kepada Allah.", "Doa perlindungan dari Nabi ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Ilmu Bermanfaat & Rezeki Halal", "Ya Allah, aku memohon kepada-Mu ilmu yang bermanfaat, rezeki yang suci, dan amal yang diterima.", "Setelah shalat Subuh.", "Nabi ﷺ mengatakan hal ini setelah salam Subuh."),
        "dua_leprosy_diseases" to DuaText("Terlindung dari Penyakit Serius", "Ya Allah, aku berlindung kepada-Mu dari vitiligo, kegilaan, kusta dan segala penyakit jahat.", "Perlindungan dari penyakit serius.", "Doa Sunnah untuk menjaga kesehatan."),
        "dua_fear_people" to DuaText("Takut pada Musuh atau Penindas", "Ya Allah, kami menempatkan-Mu di hadapan mereka dan berlindung kepada-Mu dari keburukan mereka.", "Ketika takut akan celakanya suatu bangsa atau seseorang.", "Nabi ﷺ mengatakan hal ini ketika dia takut pada suatu kaum."),
        "dua_shirk_protection" to DuaText("Perlindungan dari Syirik Tersembunyi", "Ya Allah, aku berlindung kepada-Mu dari menyekutukan sesuatu dengan-Mu dengan sengaja, dan aku memohon ampun kepada-Mu atas perbuatanku yang tanpa aku sadari.", "Agar tetap aman dari pamer dan syirik yang sembunyi-sembunyi.", "Syirik yang tersembunyi lebih tersembunyi dari pada merayapnya seekor semut."),
        "dua_rain" to DuaText("Saat Hujan", "Ya Allah, (kirimlah) hujan yang bermanfaat.", "Saat hujan.", "Hujan adalah saat dimana doa diterima."),
        "dua_after_rain" to DuaText("Setelah Hujan", "Kita diberi hujan karena karunia Allah dan rahmat-Nya.", "Setelah hujan.", "Orang yang mengatakan hal ini adalah orang yang beriman kepada Allah."),
        "dua_istisqa" to DuaText("Meminta Hujan (Istisqa)", "Ya Allah, turunkan kami hujan (tiga kali).", "Ketika tidak ada hujan.", "Nabi ﷺ mengucapkan doa ini dalam khotbah Jumat dan turun hujan."),
        "dua_heavy_rain" to DuaText("Hujan Berlebihan", "Ya Allah, (biarkan jatuh) di sekitar kami, bukan di atas kami.", "Ketika hujan terlalu deras.", "Awan menjauh melalui doa Nabi ﷺ."),
        "dua_wind" to DuaText("Saat Angin Berhembus", "Ya Allah, aku memohon kepada-Mu kebaikannya, kebaikan yang ada di dalamnya, dan kebaikan apa yang dikirimkannya, dan aku berlindung kepada-Mu dari kejahatannya, keburukan yang ada di dalamnya, dan keburukan apa yang dikirimkannya.", "Saat angin kencang atau badai bertiup.", "Nabi ﷺ mengucapkan doa ini saat badai."),
        "dua_thunder" to DuaText("Mendengar Guntur", "Maha Suci Allah yang dimuliakan oleh petir dengan puji-pujian-Nya, dan para malaikat karena takut kepada-Nya.", "Mendengar guntur — Amalan Abdullah bin az-Zubayr (RA).", "Diambil dari Surat ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Melihat Bulan Baru", "Ya Allah, biarkan bulan ini terbit di atas kami dengan berkah, iman, keselamatan dan Islam. (Wahai bulan,) Tuhanku dan Tuhanmu adalah Allah.", "Saat melihat bulan baru.", "Doa Sunnah setiap bulan baru."),
        "dua_janaza_adult" to DuaText("Doa Janaza (Dewasa)", "Ya Allah, ampunilah kami yang masih hidup dan yang sudah meninggal, yang hadir dan yang tidak hadir, muda dan tua kami, laki-laki dan perempuan kami. Ya Allah, barangsiapa di antara kami yang Engkau hidupkan, hidupkanlah dia dengan Islam, dan barangsiapa di antara kami yang Engkau matikan, matikanlah dia dengan keimanan.", "Setelah takbir ketiga salat jenazah.", "Doa Sunnah untuk orang dewasa yang sudah meninggal."),
        "dua_janaza_child" to DuaText("Doa Janaza (Anak)", "Ya Allah, jadikanlah dia sebagai pelopor (dan tuan rumah) bagi kami, jadikanlah dia sebagai pahala dan harta bagi kami, dan jadikanlah dia sebagai pemberi syafaat bagi kami yang syafaatnya diterima.", "Dalam doa pemakaman seorang anak (untuk anak perempuan ucapkan 'ij'alhā').", "Doa Sunnah yang diamalkan oleh Hanafi."),
        "dua_mayyit_awf" to DuaText("Detil Doa untuk Almarhum", "Ya Allah, ampunilah dia, kasihanilah dia, beri dia kesejahteraan dan maafkan dia. Jadikanlah penyambutannya terhormat dan luaskan kuburnya, basuhlah dia dengan air, salju, dan hujan es, dan bersihkan dia dari dosa-dosa seperti pakaian putih dibersihkan dari kotoran.", "Dalam doa pemakaman atau untuk orang yang meninggal.", "Awf bin Malik (RA) berharap dialah orang yang meninggal itu."),
        "dua_visiting_graves" to DuaText("Mengunjungi Makam", "Salam sejahtera bagi Anda, hai orang-orang beriman dan Muslim yang menghuni rumah-rumah ini. Kami juga, jika Allah menghendaki, akan bergabung dengan Anda. Saya berdoa kepada Allah untuk kesejahteraan bagi kami dan Anda.", "Saat memasuki kuburan.", "Berziarah ke kubur mengingatkan seseorang akan kematian dan akhirat."),
        "dua_closing_eyes" to DuaText("Setelah Menutup Mata Almarhum", "Ya Allah, ampunilah (nama), naikkan derajatnya di antara orang-orang yang mendapat petunjuk, jadilah penerusnya di antara orang-orang yang ditinggalkannya. Maafkan kami dan dia, ya Tuhan semesta alam; luaskan kuburnya dan isi dengan cahaya.", "Sambil menutup mata almarhum (menyebutkan namanya).", "Nabi ﷺ mengucapkan doa ini untuk Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Turut Berduka Cita (Ta'ziyah)", "Sesungguhnya kepunyaan Allah apa yang diambil-Nya dan kepunyaan-Nya apa yang diberikan-Nya, dan segala sesuatu di sisi-Nya ada masanya, maka bersabarlah dan berharap pahala.", "Memberikan belasungkawa kepada keluarga setelah kematian.", "Nabi ﷺ mengirimkan pesan ini kepada putrinya."),
        "dua_placing_in_grave" to DuaText("Menempatkan Almarhum di Kuburan", "Bismillah dan di jalan Rasulullah ﷺ.", "Saat menurunkan almarhum ke dalam kubur.", "Doa penguburan sunnah."),
        "dua_sneezing" to DuaText("Bersin", "Segala puji bagi Allah. — Semoga Allah merahmatimu. — Semoga Allah membimbing Anda dan mengatur urusan Anda dengan benar.", "Saat bersin; pendengar mengucapkan 'Yarhamukallah', lalu yang bersin menjawab.", "Ini adalah salah satu hak seorang Muslim atas Muslim lainnya."),
        "dua_toilet_enter" to DuaText("Memasuki Toilet", "Dengan menyebut nama Allah. Ya Allah, aku berlindung kepada-Mu dari jin najis laki-laki dan perempuan.", "Sebelum melangkah ke toilet dengan kaki kiri.", "Bismillah menjadi sekat antara jin dan manusia."),
        "dua_toilet_exit" to DuaText("Meninggalkan Toilet", "(Ya Allah,) aku mohon ampun kepada-Mu.", "Saat keluar dari toilet dengan kaki kanan.", "Nabi ﷺ mengatakan hal ini saat meninggalkan toilet."),
        "dua_thanking" to DuaText("Berterima kasih kepada Seseorang", "Semoga Allah membalas Anda dengan kebaikan.", "Ketika seseorang membantu Anda.", "Siapapun yang mengatakan ini telah menyatakan terima kasihnya sepenuhnya."),
        "dua_love_for_allah" to DuaText("Ketika Seseorang Mengatakan 'Aku Mencintaimu Karena Allah'", "Semoga Dia (Allah), yang olehnya kamu mencintaiku, mencintaimu.", "Ketika seseorang mengatakan 'Aku mencintaimu karena Allah'.", "Sunnah membalas cinta karena Allah."),
        "dua_seeing_muslim_smile" to DuaText("Salam (Salaam)", "Salam sejahtera bagi Anda, dan rahmat Allah dan berkah-Nya.", "Saat bertemu dengan seorang Muslim.", "Mengucapkan salam secara lengkap menghasilkan tiga puluh amal shaleh."),
        "dua_dressing" to DuaText("Berpakaian", "Segala puji bagi Allah yang telah membekaliku dengan ini dan menyediakannya untukku tanpa ada daya dan tenaga dari pihakku.", "Saat berpakaian.", "Kabar gembira pengampunan dosa masa lalu."),
        "dua_rooster_donkey" to DuaText("Mendengar Ayam atau Keledai", "Ya Allah, aku mohon kepada-Mu (ayam jantan) karunia-Mu. — Aku berlindung kepada Allah dari setan, si terkutuk (keledai).", "Mendengar ayam jago meminta karunia Allah; ketika mendengar seekor keledai mencari perlindungan dari setan.", "Ayam jantan melihat malaikat dan keledai melihat setan."),
        "dua_something_liked" to DuaText("Melihat Sesuatu yang Mengagumkan (Melawan Mata Jahat)", "Apa yang Allah kehendaki. Ya Allah, berkahilah itu.", "Saat melihat sesuatu yang mengagumkan milik seseorang, berdoalah memohon berkah.", "Berdoa memohon berkah mencegah mata jahat."),
        "dua_sell_buy_debt_repaid" to DuaText("Saat Membayar Hutang", "Semoga Allah memberkati Anda dalam keluarga dan kekayaan Anda.", "Bagi pemberi pinjaman pada saat melunasi utangnya.", "Pengembalian pinjaman adalah ucapan terima kasih dan pembayaran kembali."),
        "dua_talbiyah" to DuaText("Talbiyah", "Inilah aku, ya Allah, inilah aku. Inilah aku, kamu tak punya pasangan, inilah aku. Sesungguhnya segala puji, nikmat dan kekuasaan milik-Mu. Anda tidak memiliki pasangan.", "Dengan lantang setelah masuk ihram.", "Lambang Haji dan Umroh."),
    )
}
